35	// The graphics register window (the SETW / GETW / GETWF per-(warp,lane,slot)
36	// slot file) is shared by all fixed-function consumers: the RTU streams the ray
37	// / hit window through it, TEX (vx_tex4) reads its u,v payload and writes its
38	// texel, and OM (vx_om4) reads its quad payload. It is therefore available
39	// whenever ANY of those blocks is built — decoupled from the RTU. This mirrors
40	// the RTL, where VX_gfx_window_pkg.sv lives at the SFU level, not inside the RTU
41	// core. The RtuType op set (which carries SETW/GETW/GETWF alongside the
42	// RTU-only CB_RET/TRACE2/WAIT2) and IntrRtuArgs are gated on this macro; the
43	// RTU-only ops are still only *decoded* under VX_CFG_EXT_RTU_ENABLE.
44	#if defined(VX_CFG_EXT_OM_ENABLE) || defined(VX_CFG_EXT_TEX_ENABLE) || defined(VX_CFG_EXT_RTU_ENABLE) || defined(VX_CFG_EXT_RASTER_ENABLE)
45	#define VX_GFX_WINDOW_ENABLE
46	#endif
