78	// Decode a packed kernel bar_id (local_group_id | (bar_no << 8)) to a flat barrier index.
79	// Preserves the global barrier flag (bit 31).
80	inline uint32_t bar_decode_id(uint32_t bar_id_raw, uint32_t num_barriers) {
81	  uint32_t cta_no = bar_id_raw & 0xffu;
82	  uint32_t bar_no = (bar_id_raw >> 8) & 0x7fffffu;
83	  return (cta_no * num_barriers + bar_no) | (bar_id_raw & 0x80000000u);
84	}
