155	struct RegOpd {
156	  RegType type = RegType::None;
157	  uint32_t idx = 0;
158	
159	  uint32_t id() const {
160	    if (type == RegType::None)
161	      return 0;
162	    // unique register id embedding the type
163	    return (((int)(type)-1) << LOG_NUM_REGS) | idx;
164	  }
165	
166	  friend std::ostream &operator<<(std::ostream &os, const RegOpd& reg) {
167	    os << reg.type << reg.idx;
168	    return os;
169	  }
170	
171	  constexpr static uint32_t ID_BITS = log2ceil((int)RegType::Count) + LOG_NUM_REGS;
172	};
