391	// Memory-op tag. Always-present ops (LD/ST/FLUSH) at the low values,
392	// VX_CFG_EXT_A_ENABLE atomic family contiguous at 3..13.
393	enum class MemOp : uint8_t {
394	  // Always-present (independent of VX_CFG_EXT_A_ENABLE)
395	  LD        = 0,
396	  ST        = 1,
397	  FLUSH     = 2,
398	  // Atomic family (only meaningful when VX_CFG_EXT_A_ENABLE)
399	  AMO_LR    = 3,
400	  AMO_SC    = 4,
401	  AMO_SWAP  = 5,
402	  AMO_ADD   = 6,
403	  AMO_AND   = 7,
404	  AMO_OR    = 8,
405	  AMO_XOR   = 9,
406	  // MIN/MAX collapse signed/unsigned variants; the LSU sets
407	  // `flags.amo_unsigned` for AMOMINU/AMOMAXU and the AMO ALU branches on it.
408	  AMO_MIN   = 10,
409	  AMO_MAX   = 11,
410	};
411	
412	inline bool memop_is_atomic(MemOp op) {
413	  return op >= MemOp::AMO_LR && op <= MemOp::AMO_MAX;
414	}
415	inline bool memop_is_amo_rmw(MemOp op) {
416	  return op >= MemOp::AMO_SWAP && op <= MemOp::AMO_MAX;
417	}
418	inline bool memop_is_write(MemOp op) {
419	  return op == MemOp::ST || op == MemOp::AMO_SC || memop_is_amo_rmw(op);
420	}
421	inline bool memop_is_amo(MemOp op) { return memop_is_atomic(op); }
