423	// Memory-request flags.
424	struct MemFlags {
425	  union {
426	    uint32_t raw;
427	    struct {
428	      uint32_t strsp        : 1;  // bit 0: store-response enabled (opt-in)
429	      uint32_t io           : 1;  // bit 1: uncacheable I/O
430	      uint32_t local        : 1;  // bit 2: LMEM port
431	      uint32_t amo_unsigned : 1;  // bit 3: MIN/MAX signedness (1=unsigned)
432	    #ifdef VX_CFG_EXT_DXA_ENABLE
433	      // DXA completion sideband — populated only on DXA's LMEM-DMA writes.
434	      // notify_bar_id carries the RAW (kernel-encoded) bar handle:
435	      //   bits[7:0]   = cta_local_id (= get_local_group_id())
436	      //   bits[N+7:8] = user bar_no (N = CLOG2(NUM_BARRIERS))
437	      // Multicast adds cta_warp_idx into the low byte, so the field must
438	      // be wide enough to hold (bar_no << 8) | (MAX_CTAS_per_core - 1).
439	      // For NUM_BARRIERS = 8 and NUM_WARPS ≤ 16, that's at most 11 bits;
440	      // 16 bits leaves headroom for larger configs.
441	      uint32_t dxa_notify_done   : 1;   // bit 4
442	      uint32_t dxa_notify_bar_id : 16;  // bits 5..20
443	    #endif
444	    };
445	  };
446	
447	  MemFlags() : raw(0) {}
448	  MemFlags(uint32_t r) : raw(r) {}
449	
450	  bool any()  const { return raw != 0; }
451	  bool none() const { return raw == 0; }
452	
453	  bool operator==(const MemFlags& o) const { return raw == o.raw; }
454	  bool operator!=(const MemFlags& o) const { return raw != o.raw; }
455	
456	  friend std::ostream& operator<<(std::ostream& os, const MemFlags& f) {
457	    os << "0x" << std::hex << f.raw << std::dec;
458	    return os;
459	  }
460	};
461	static_assert(sizeof(MemFlags) == sizeof(uint32_t), "MemFlags must be 32-bit");
462	
