671	// RTU (Ray-Tracing Unit) — PRISM ops.
672	// All share CUSTOM1 / funct3=5; sub-op (funct2) selects.
673	//   sub-op=0 SET    write one RTU reg (R-type, slot in funct7[6:2])
674	//   sub-op=1 GET    read one RTU reg
675	//   sub-op=2 TRACE  async ray issue; returns handle
676	//   sub-op=3 WAIT   block on handle; returns terminal status
677	//   sub-op=4 CB_RET Phase 2: release a yielded ray with an action code
678	//                   (ACCEPT / IGNORE / TERMINATE). rs1 = action.
679	enum class RtuType {
680	  SETW,       // funct3=6 sub1: in-trap callback regfile write (§5.5)
681	  CB_RET,     // funct3=6 sub0: release a parked callback context
682	  TRACE2,   // ISA v2: single-issue trace macro-op (rtu_isa_v2_proposal.md §5.1)
683	  WAIT2,    // SINGLE-OP block — parks until terminal, returns status
684	            // (reuses the v1 park/revive so it survives an async callback trap)
685	  GETWF,    // FP windowed regfile read (collapses N contiguous
686	            // float-slot vx_rt_get into one macro-op; callback read path §5.5)
687	  GETW,     // GP twin of GETWF (integer slots, no NaN-box). vx_rt_wait2
688	            // reads t/u/v via GETWF and the IDs via GETW after the WAIT2 block.
689	  GETWS,    // GP windowed read, but the window's warp dimension is indexed by
690	            // rs1 (block_idx/slot) instead of the executing wid — the FWD-v2
691	            // fragment-record read (funct3=4). Decouples the read from the
692	            // minted warp-id so the raster unit seeds by slot.
693	};
694	
695	struct IntrRtuArgs {
696	  uint32_t slot  : 6;  // RTU register-file slot ID; GETWF: window start slot
697	  uint32_t uop   : 4;  // macro-op micro-op index (TRACE2/WAIT2/GETWF)
698	  uint32_t count : 4;  // GETWF: number of contiguous slots in the window (1..8)
699	};
700	
701	inline std::ostream &operator<<(std::ostream &os, const RtuType& type) {
702	  switch (type) {
703	  case RtuType::SETW:   os << "RT.SETW";   break;
704	  case RtuType::CB_RET: os << "RT.CB_RET"; break;
705	  case RtuType::TRACE2: os << "RT.TRACE2"; break;
706	  case RtuType::WAIT2:  os << "RT.WAIT2";  break;
707	  case RtuType::GETWF:  os << "RT.GETWF";  break;
708	  case RtuType::GETW:   os << "RT.GETW";   break;
709	  case RtuType::GETWS:  os << "RT.GETWS";  break;
710	  default: os << "?"; break;
711	  }
712	  return os;
713	}
