901	class IArbiterImpl {
902	public:
903	  IArbiterImpl() {}
904	  virtual ~IArbiterImpl() {}
905	  virtual uint32_t grant(const BitVector<>& requests) = 0;
906	  virtual uint32_t grant(const BitVector<>& requests, const BitVector<>& suppress) {
907	    // Default: ignore suppress mask, subclasses may override.
908	    __unused (suppress);
909	    return this->grant(requests);
910	  }
911	  virtual void reset() = 0;
912	};
913	
914	class PriorityArbiter : public IArbiterImpl {
915	public:
916	  PriorityArbiter(uint32_t size) : size_(size) {
917	    this->reset();
918	  }
919	
920	  uint32_t grant(const BitVector<>& requests) override {
921	    assert(requests.size() == size_);
922	    for (uint32_t i = 0; i < size_; ++i) {
923	      if (requests.test(i)) {
924	        return i;
925	      }
926	    }
927	    return -1;
928	  }
929	
930	  void reset() override {
931	    //--
932	  }
933	private:
934	  uint32_t size_;
935	};
936	
937	class RoundRobinArbiter : public IArbiterImpl {
938	public:
939	  RoundRobinArbiter(uint32_t size) : size_(size) {
940	    this->reset();
941	  }
942	
943	  uint32_t grant(const BitVector<>& requests) override {
944	    assert(requests.size() == size_);
945	    uint32_t start = (last_grant_ + 1) % size_;
946	    for (uint32_t i = 0; i < size_; ++i) {
947	      uint32_t idx = (start + i) % size_;
948	      if (requests.test(idx)) {
949	        last_grant_ = idx;
950	        return idx;
951	      }
952	    }
953	    return -1;
954	  }
955	
956	  void reset() override {
957	    last_grant_ = 0;
958	  }
959	
960	private:
961	  uint32_t size_;
962	  uint32_t last_grant_;
963	};
964	
965	class MatrixArbiter : public IArbiterImpl {
966	public:
967	  MatrixArbiter(uint32_t size)
968	    : size_(size)
969	    , priority_matrix_(size, std::vector<bool>(size)) {
970	    this->reset();
971	  }
972	
973	  uint32_t grant(const BitVector<>& requests) override {
974	    assert(requests.size() == size_);
975	    for (uint32_t i = 0; i < size_; ++i) {
976	      if (requests[i]) {
977	        // Check if this request has the highest priority by comparing it
978	        bool highest_priority = true;
979	        for (uint32_t j = 0; j < size_; ++j) {
980	          if (requests[j] && priority_matrix_[i][j]) {
981	            highest_priority = false;
982	            break;
983	          }
984	        }
985	
986	        if (highest_priority) {
987	          for (uint32_t j = 0; j < size_; ++j) {
988	            if (i != j) {
989	              priority_matrix_[i][j] = false;
990	              priority_matrix_[j][i] = true;
991	            }
992	          }
993	          return i;
994	        }
995	      }
996	    }
997	    return -1;
998	  }
999	
1000	  void reset() override {
1001	    for (uint32_t i = 0; i < size_; ++i) {
1002	      priority_matrix_[i].resize(size_);
1003	      for (uint32_t j = i + 1; j < size_; ++j) {
1004	        priority_matrix_[i][j] = true;
1005	      }
1006	    }
1007	  }
1008	
1009	private:
1010	  uint32_t size_;
1011	  std::vector<std::vector<bool>> priority_matrix_;
1012	};
1013	
1014	class GTOArbiter : public IArbiterImpl {
1015	public:
1016	  GTOArbiter(uint32_t size)
1017	    : size_(size)
1018	    , age_(size, 0)
1019	    , last_grant_(-1u) {
1020	    this->reset();
1021	  }
1022	
1023	  uint32_t grant(const BitVector<>& requests) override {
1024	    BitVector<> no_suppress(size_);
1025	    return this->grant(requests, no_suppress);
1026	  }
1027	
1028	  uint32_t grant(const BitVector<>& requests, const BitVector<>& suppress) override {
1029	    assert(requests.size() == size_);
1030	    assert(suppress.size() == size_);
1031	    // greedy: keep granting same requester if still active and unsuppressed
1032	    if (last_grant_ < size_ && requests.test(last_grant_) && !suppress.test(last_grant_)) {
1033	      this->update_ages(requests, last_grant_);
1034	      return last_grant_;
1035	    }
1036	    // Then-Oldest: find the unsuppressed requester with the highest age
1037	    uint32_t best = -1u;
1038	    uint32_t best_age = 0;
1039	    for (uint32_t i = 0; i < size_; ++i) {
1040	      if (requests.test(i) && !suppress.test(i) && (best == -1u || age_[i] > best_age)) {
1041	        best = i;
1042	        best_age = age_[i];
1043	      }
1044	    }
1045	    if (best != -1u) {
1046	      last_grant_ = best;
1047	      this->update_ages(requests, best);
1048	    }
1049	    return best;
1050	  }
1051	
1052	  void reset() override {
1053	    std::fill(age_.begin(), age_.end(), 0);
1054	    last_grant_ = -1u;
1055	  }
1056	
1057	private:
1058	  void update_ages(const BitVector<>& requests, uint32_t granted) {
1059	    for (uint32_t i = 0; i < size_; ++i) {
1060	      if (i == granted || !requests.test(i)) {
1061	        age_[i] = 0;
1062	      } else {
1063	        ++age_[i];
1064	      }
1065	    }
1066	  }
1067	
1068	  uint32_t size_;
1069	  std::vector<uint32_t> age_;
1070	  uint32_t last_grant_;
1071	};
