1190	// Maps RVA AmoType → MemOp. Signed/unsigned MIN/MAX variants collapse onto
1191	// MemOp::AMO_MIN/MAX; the unsigned distinction rides on flags.amo_unsigned
1192	// (set per-AMO by the LSU via amo_is_unsigned() below).
1193	inline MemOp amo_to_memop(AmoType t) {
1194	  switch (t) {
1195	  case AmoType::LR:      return MemOp::AMO_LR;
1196	  case AmoType::SC:      return MemOp::AMO_SC;
1197	  case AmoType::AMOADD:  return MemOp::AMO_ADD;
1198	  case AmoType::AMOSWAP: return MemOp::AMO_SWAP;
1199	  case AmoType::AMOXOR:  return MemOp::AMO_XOR;
1200	  case AmoType::AMOOR:   return MemOp::AMO_OR;
1201	  case AmoType::AMOAND:  return MemOp::AMO_AND;
1202	  case AmoType::AMOMIN:
1203	  case AmoType::AMOMINU: return MemOp::AMO_MIN;
1204	  case AmoType::AMOMAX:
1205	  case AmoType::AMOMAXU: return MemOp::AMO_MAX;
1206	  }
1207	  std::abort();
1208	}
