1210	// True for RVA MIN/MAX unsigned variants; carried as flags.amo_unsigned.
1211	inline bool amo_is_unsigned(AmoType t) {
1212	  return t == AmoType::AMOMINU || t == AmoType::AMOMAXU;
1213	}
