1295	class HashTable {
1296	public:
1297	  typedef T DataType;
1298	
1299	  HashTable(uint32_t capacity)
1300	    : entries_(capacity)
1301	    , size_(0)
1302	  {}
1303	
1304	  bool empty() const {
1305	    return (0 == size_);
1306	  }
1307	
1308	  bool full() const {
1309	    return (size_ == entries_.size());
1310	  }
1311	
1312	  uint32_t size() const {
1313	    return size_;
1314	  }
1315	
1316	  bool contains(uint32_t index) const {
1317	    return entries_.at(index).first;
1318	  }
1319	
1320	  const T& at(uint32_t index) const {
1321	    auto& entry = entries_.at(index);
1322	    assert(entry.first);
1323	    return entry.second;
1324	  }
1325	
1326	  T& at(uint32_t index) {
1327	    auto& entry = entries_.at(index);
1328	    assert(entry.first);
1329	    return entry.second;
1330	  }
1331	
1332	  uint32_t allocate(const T& value) {
1333	    for (uint32_t i = 0, n = entries_.size(); i < n; ++i) {
1334	      auto& entry = entries_.at(i);
1335	      if (!entry.first) {
1336	        entry.first = true;
1337	        entry.second = value;
1338	        ++size_;
1339	        return i;
1340	      }
1341	    }
1342	    assert(false);
1343	    return -1;
1344	  }
1345	
1346	  void release(uint32_t index) {
1347	    auto& entry = entries_.at(index);
1348	    assert(entry.first);
1349	    entry.first = false;
1350	    --size_;
1351	  }
1352	
1353	  void clear() {
1354	    for (uint32_t i = 0, n = entries_.size(); i < n; ++i) {
1355	      auto& entry = entries_.at(i);
1356	      entry.first = false;
1357	    }
1358	    size_ = 0;
1359	  }
1360	
1361	private:
1362	  std::vector<std::pair<bool, T>> entries_;
1363	  uint32_t size_;
1364	};
