1436	  typedef Type ReqType;
1437	
1438	  struct RspType {
1439	    Type     data;
1440	    uint32_t input;
1441	
1442	    RspType(const Type& _data, uint32_t _input = 0)
1443	      : data(_data)
1444	      , input(_input)
1445	    {}
1446	
1447	    operator Type() const {
1448	      return data;
1449	    }
1450	  };
1451	
1452	  std::vector<SimChannel<ReqType>> Inputs;
1453	  std::vector<SimChannel<RspType>> Outputs;
1454	
1455	  TxArbiter(
1456	    const SimContext& ctx,
1457	    const char* name,
1458	    ArbiterType type,
1459	    uint32_t num_inputs,
1460	    uint32_t num_outputs,
1461	    uint32_t delay
1462	  ) : SimObject<TxArbiter<Type>>(ctx, name)
1463	    , Inputs(num_inputs, this)
1464	    , Outputs(num_outputs, this)
1465	    , delay_(delay)
1466	    , lg2_num_reqs_(log2ceil(num_inputs / num_outputs))
1467	    , arbiters_(num_outputs, {type, 1u << lg2_num_reqs_})
1468	  {
1469	    assert(num_inputs <= 64);
1470	    assert(num_outputs <= 64);
1471	    assert(num_inputs >= num_outputs);
1472	
1473	    // bypass mode
1474	    if (num_inputs == num_outputs) {
1475	      for (uint32_t i = 0; i < num_inputs; ++i) {
1476	        Inputs.at(i).bind(&Outputs.at(i));
1477	      }
1478	    }
1479	  }
1480	
