1482	    const SimContext& ctx,
1483	    const char* name,
1484	    ArbiterType type,
1485	    uint32_t num_inputs,
1486	    uint32_t num_outputs
1487	  ) : TxArbiter<Type>(ctx, name, type, num_inputs, num_outputs,
1488	      ((num_inputs > 2) || (num_outputs > 2)) ? 1 : 0)
1489	  {}
1490	
1491	protected:
1492	  void on_reset();
1493	  void on_tick();
1494	
1495	  uint32_t delay_;
