1500	};
1501	
1502	template <typename Type>
1503	void TxArbiter<Type>::on_reset() {
1504	  for (auto& arb : arbiters_) {
1505	    arb.reset();
1506	  }
1507	}
1508	
1509	template <typename Type>
1510	void TxArbiter<Type>::on_tick() {
1511	  uint32_t I = Inputs.size();
1512	  uint32_t O = Outputs.size();
1513	  uint32_t R = 1 << lg2_num_reqs_;
1514	
1515	  // skip bypass mode
1516	  if (I == O)
1517	    return;
1518	
1519	  // process inputs
1520	  for (uint32_t o = 0; o < O; ++o) {
1521	    BitVector<> requests(R);
1522	    for (uint32_t r = 0; r < R; ++r) {
1523	      uint32_t i = o * R + r;
1524	      if (i >= I)
1525	        continue;
1526	      requests.set(r, !Inputs.at(i).empty());
1527	    }
1528	    if (requests.any()) {
1529	      uint32_t g = arbiters_.at(o).grant(requests);
1530	      uint32_t i = o * R + g;
1531	      auto& req_in = Inputs.at(i);
1532	      auto& req = req_in.peek();
1533	      if (Outputs.at(o).try_send(RspType(req, i), delay_)) {
1534	        DT(4, this->name() << " req" << i << "_" << o << ": " << req);
1535	        req_in.pop();
1536	      }
1537	    }
1538	  }
1539	}
