1560	    }
1561	  };
1562	
1563	  std::vector<SimChannel<ReqType>> Inputs;
1564	  std::vector<SimChannel<RspType>> Outputs;
1565	
1566	  TxCrossBar(
1567	    const SimContext& ctx,
1568	    const char* name,
1569	    uint32_t num_inputs,
1570	    uint32_t num_outputs,
1571	    std::function<uint32_t(const Type& req)> output_sel,
1572	    uint32_t delay
1573	  )
1574	    : SimObject<TxCrossBar<Type>>(ctx, name)
1575	    , Inputs(num_inputs, this)
1576	    , Outputs(num_outputs, this)
1577	    , delay_(delay)
1578	    , lg2_inputs_(log2ceil(num_inputs))
1579	    , lg2_outputs_(log2ceil(num_outputs))
1580	    , output_sel_(output_sel)
1581	    , collisions_(0) {
1582	    assert(num_inputs <= 64);
1583	    assert(num_outputs <= 64);
1584	    assert(ispow2(num_outputs));
1585	    assert(output_sel != nullptr);
1586	
1587	    // bypass mode
1588	    if (num_inputs == 1 && num_outputs == 1) {
1589	      Inputs.at(0).bind(&Outputs.at(0));
1590	    }
1591	  }
1592	
1593	  TxCrossBar(
1594	    const SimContext& ctx,
1595	    const char* name,
1596	    uint32_t num_inputs,
1597	    uint32_t num_outputs,
1598	    std::function<uint32_t(const Type& req)> output_sel
1599	  ) : TxCrossBar<Type>(ctx, name, num_inputs, num_outputs,
1600	      output_sel, ((num_inputs > 2) || (num_outputs > 2)) ? 1 : 0)
1601	  {}
1602	
