1604	    return collisions_;
1605	  }
1606	
1607	protected:
1608	  void on_reset() {
1609	    //--
1610	  }
1611	  void on_tick();
1612	
1613	  uint32_t delay_;
1614	  uint32_t lg2_inputs_;
1615	  uint32_t lg2_outputs_;
1616	  std::function<uint32_t(const Type& req)> output_sel_;
1617	  uint64_t collisions_;
1618	
1619	  friend class SimObject<TxCrossBar<Type>>;
1620	};
1621	
1622	template <typename Type>
1623	void TxCrossBar<Type>::on_tick() {
1624	  uint32_t I = Inputs.size();
1625	  uint32_t O = Outputs.size();
1626	  if (I == 1 && O == 1)
1627	    return;
1628	
1629	  // process incoming requests
1630	  for (uint32_t o = 0; o < O; ++o) {
1631	    int32_t input_idx = -1;
1632	    bool has_collision = false;
1633	    for (uint32_t i = 0; i < I; ++i) {
1634	      auto& req_in = Inputs.at(i);
1635	      if (req_in.empty())
1636	        continue;
1637	      auto& req = req_in.peek();
1638	      uint32_t output_idx = 0;
1639	      if (lg2_outputs_ != 0) {
1640	        // select output index
1641	        output_idx = output_sel_(req);
1642	        // skip if input is not going to current output
1643	        if (output_idx != o)
1644	          continue;
1645	      }
1646	      if (input_idx != -1) {
1647	        has_collision = true;
1648	        break;
1649	      }
1650	      input_idx = i;
1651	    }
1652	    if (input_idx != -1) {
1653	      auto& req_in = Inputs.at(input_idx);
1654	      auto& req = req_in.peek();
1655	      if (Outputs.at(o).try_send(RspType(req, input_idx), delay_)) {
1656	        DT(4, this->name() << " req" << input_idx << "_" << o << ": " << req);
1657	        req_in.pop();
1658	      }
1659	      collisions_ += has_collision;
1660	    }
1661	  }
1662	}
