1666	template <typename Req, typename Rsp>
1667	class TxRxArbiter : public SimObject<TxRxArbiter<Req, Rsp>> {
1668	public:
1669	  using Ptr = std::shared_ptr<TxRxArbiter<Req, Rsp>>;
1670	  typedef Req ReqType;
1671	  typedef Rsp RspType;
1672	
1673	  std::vector<SimChannel<Req>>  ReqIn;
1674	  std::vector<SimChannel<Rsp>>  RspOut;
1675	
1676	  std::vector<SimChannel<Req>>  ReqOut;
1677	  std::vector<SimChannel<Rsp>>  RspIn;
1678	
1679	  TxRxArbiter(
1680	    const SimContext& ctx,
1681	    const char* name,
1682	    ArbiterType type,
1683	    uint32_t num_inputs,
1684	    uint32_t num_outputs,
1685	    uint32_t req_delay,
1686	    uint32_t rsp_delay
1687	  )
1688	    : SimObject<TxRxArbiter<Req, Rsp>>(ctx, name)
1689	    , ReqIn(num_inputs, this)
1690	    , RspOut(num_inputs, this)
1691	    , ReqOut(num_outputs, this)
1692	    , RspIn(num_outputs, this)
1693	    , arbiter_(nullptr)
1694	    , rsp_delay_(rsp_delay)
1695	    , lg2_num_reqs_(log2ceil(num_inputs / num_outputs))
1696	  {
1697	    if (num_inputs != num_outputs) {
1698	      arbiter_ = ReqArb::Create(name, type, num_inputs, num_outputs, req_delay);
1699	      for (uint32_t i = 0; i < num_inputs; ++i) {
1700	        ReqIn.at(i).bind(&arbiter_->Inputs.at(i));
1701	      }
1702	      for (uint32_t o = 0; o < num_outputs; ++o) {
1703	        arbiter_->Outputs.at(o).bind(&ReqOut.at(o),
1704	          [lg2_num_reqs = lg2_num_reqs_](const typename ReqArb::RspType& arb_rsp) {
1705	            Req req(arb_rsp.data);
1706	            if (lg2_num_reqs != 0) {
1707	              uint32_t r = arb_rsp.input & ((1 << lg2_num_reqs) - 1);
1708	              req.tag = (req.tag << lg2_num_reqs) | r;
1709	            }
1710	            return req;
1711	          });
1712	      }
1713	    } else {
1714	      // bypass mode
1715	      for (uint32_t i = 0; i < num_inputs; ++i) {
1716	        ReqIn.at(i).bind(&ReqOut.at(i));
1717	        RspIn.at(i).bind(&RspOut.at(i));
1718	      }
1719	    }
1720	  }
1721	
1722	  TxRxArbiter(
1723	    const SimContext& ctx,
1724	    const char* name,
1725	    ArbiterType type,
1726	    uint32_t num_inputs,
1727	    uint32_t num_outputs
1728	  ) : TxRxArbiter<Req, Rsp>(ctx, name, type, num_inputs, num_outputs,
1729	      ((num_inputs > 2) || (num_outputs > 2)) ? 1 : 0,
1730	      ((num_inputs > 2) || (num_outputs > 2)) ? 1 : 0)
1731	  {}
