1746	};
1747	
1748	template <typename Req, typename Rsp>
1749	void TxRxArbiter<Req, Rsp>::on_tick() {
1750	  if (!arbiter_)
1751	    return;
1752	
1753	  uint32_t O = ReqOut.size();
1754	  uint32_t R = 1 << lg2_num_reqs_;
1755	
1756	  // process outgoing responses
1757	  for (uint32_t o = 0; o < O; ++o) {
1758	    auto& rsp_in = RspIn.at(o);
1759	    if (!rsp_in.empty()) {
1760	      auto& rsp = rsp_in.peek();
1761	      uint32_t r = 0;
1762	      Rsp out_rsp(rsp);
1763	      if (lg2_num_reqs_ != 0) {
1764	        r = rsp.tag & (R-1);
1765	        out_rsp.tag = rsp.tag >> lg2_num_reqs_;
1766	      }
1767	      uint32_t i = o * R + r;
1768	      if (RspOut.at(i).try_send(out_rsp, rsp_delay_)) {
1769	        DT(4, this->name() << " rsp" << o << "_" << i << ": " << out_rsp);
1770	        rsp_in.pop();
1771	      }
1772	    }
1773	  }
1774	}
