1879	    BitVector<> requests(O);
1880	    for (uint32_t o = 0; o < O; ++o) {
1881	      auto& rsp_in = RspIn.at(o);
1882	      if (rsp_in.empty())
1883	        continue;
1884	      auto& rsp = rsp_in.peek();
1885	      // skip if response is not going to current input
1886	      if (lg2_inputs_ != 0) {
1887	        uint32_t input_idx = rsp.tag & (R-1);
1888	        if (input_idx != i)
1889	          continue;
1890	      }
1891	      requests.set(o);
1892	    }
1893	    if (requests.any()) {
1894	      uint32_t g = arbiter_.grant(requests);
1895	      auto& rsp_in = RspIn.at(g);
1896	      auto& rsp = rsp_in.peek();
1897	      Rsp out_rsp(rsp);
1898	      if (lg2_inputs_ != 0) {
1899	        out_rsp.tag = rsp.tag >> lg2_inputs_;
1900	      }
1901	      if (RspOut.at(i).try_send(out_rsp, rsp_delay_)) {
1902	        DT(4, this->name() << " rsp" << g << "_" << i << ": " << out_rsp);
1903	        rsp_in.pop();
1904	      }
1905	    }
1906	  }
1907	}
1908	
1909	using LsuArbiter  = TxRxArbiter<LsuReq, LsuRsp>;
1910	using MemArbiter  = TxRxArbiter<MemReq, MemRsp>;
1911	using MemCrossBar = TxRxCrossBar<MemReq, MemRsp>;
1912	
1913	}
1914

